def pearson(u, v):
    n = len(u)
    if n < 6:
        return None
    mu, mv = sum(u) / n, sum(v) / n
    su = math.sqrt(sum((t - mu) ** 2 for t in u))
    sv = math.sqrt(sum((t - mv) ** 2 for t in v))
    if su == 0 or sv == 0:
        return None
    return sum((u[i] - mu) * (v[i] - mv) for i in range(n)) / (su * sv)
